-- LanguageTool — Перефразування і граматика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'languagetool.org' OR LOWER(`name`) = LOWER('LanguageTool'))), 1, 0);
