INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ProWritingAid', NULL, 'https://prowritingaid.com', NULL, NULL, 'Помічник для авторів книжок і довгих текстів: перевірка граматики та стилю, понад 25 аналітичних звітів, AI-критика розділів і інструменти планування історії.', 'An assistant for book authors and long-form writers: grammar and style checks, 25+ analysis reports, AI chapter critiques and story-planning tools.', 'ProWritingAid орієнтований на тих, хто пише книжки та великі тексти. Окрім перевірки граматики й стилю, він дає понад 25 звітів про текст — повтори, темп, діалоги, читабельність тощо, — построкове редагування, AI-критику розділів з відгуком про сюжет і персонажів, власні стильові посібники та інструменти для планування історії. Старший тариф додає спільноту авторів, живі воркшопи й щоденні письменницькі спринти. Тарифи: Free — базова перевірка, 2 звіти на день (до 500 слів); Premium — $30 на місяць, $120 на рік або $399 довічно; Premium Pro — $36 на місяць, $144 на рік або $699 довічно.', 'ProWritingAid is aimed at people who write books and long texts. Besides grammar and style checks, it offers 25+ reports on your writing — repetition, pacing, dialogue, readability and more — line editing, AI chapter critiques with feedback on plot and characters, custom style guides and story-planning tools. The top plan adds a writers'' community, live workshops and daily writing sprints. Plans: Free — basic checks, 2 reports a day (up to 500 words); Premium — $30 a month, $120 a year or $399 lifetime; Premium Pro — $36 a month, $144 a year or $699 lifetime.', 'Граматика, стиль і построкове редагування
25+ аналітичних звітів про текст
AI-критика розділів
Планування історії та стильові посібники', 'Grammar, style and line editing
25+ analysis reports
AI chapter critiques
Story planning and style guides', 'Письменники, автори нон-фікшн і блогери, які працюють з довгими текстами англійською.', 'Novelists, non-fiction authors and bloggers working on long texts in English.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
