-- Hemingway Editor — Перефразування і граматика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hemingwayapp.com' OR LOWER(`name`) = LOWER('Hemingway Editor'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hemingway Editor', NULL, 'https://hemingwayapp.com', NULL, NULL, 'Редактор, що робить текст ясним і читабельним: підсвічує складні речення, пасивний стан і зайві слова, а версія Plus з AI виправляє граматику та переписує речення.', 'An editor that makes writing clear and readable: it highlights hard sentences, passive voice and unnecessary words, and the AI-powered Plus version fixes grammar and rewrites sentences.', 'Hemingway Editor допомагає писати просто й зрозуміло. Він оцінює рівень читабельності тексту й підсвічує надто довгі та складні речення, пасивний стан, зайві прислівники й слова, для яких є простіші заміни. Безкоштовні онлайн-інструменти включають перевірку граматики, перефразування, AI-коректуру та перевірку читабельності. Hemingway Editor Plus додає AI-функції — виправлення граматики й орфографії, переписування речень, підбір синонімів — з лімітом на кількість речень. Є 2-тижневий безкоштовний пробний період; при річній оплаті Plus коштує $100 на рік (5 000 AI-речень на місяць) або $150 на рік (10 000 речень), командний тариф — $150 на рік за користувача.', 'Hemingway Editor helps you write plainly and clearly. It grades the readability of your text and highlights overly long and complex sentences, passive voice, unnecessary adverbs and words with simpler alternatives. Free online tools include a grammar checker, paraphrasing, an AI proofreader and a readability checker. Hemingway Editor Plus adds AI features — grammar and spelling fixes, sentence rewrites and synonyms — with a monthly sentence limit. There is a 2-week free trial; billed annually, Plus costs $100 a year (5,000 AI sentences a month) or $150 a year (10,000 sentences), and the team plan is $150 a year per user.', 'Оцінка читабельності тексту
Підсвічування складних речень і пасиву
AI-виправлення граматики й переписування (Plus)
Безкоштовні онлайн-інструменти', 'Readability grading
Highlights hard sentences and passive voice
AI grammar fixes and rewrites (Plus)
Free online tools', 'Автори, маркетологи, журналісти й студенти, які хочуть писати коротко й ясно англійською.', 'Writers, marketers, journalists and students who want to write concisely and clearly in English.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
