INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PromptHub', NULL, 'https://www.prompthub.us', NULL, NULL, 'Спільнотна платформа для керування промптами: версії, пакетне тестування, оцінювання, конвеєри та API, з безкоштовним стартом для всієї команди.', 'A community-first prompt management platform: versioning, batch testing, evaluations, pipelines and an API, free to start for the whole team.', 'PromptHub допомагає зберігати, тестувати й покращувати промпти. Промпти мають історію версій, їх можна запускати пакетами на різних моделях і порівнювати результати, налаштовувати оцінювання та конвеєри з кількох кроків і викликати через API. Є спільнота з публічними промптами. Тарифи: Free — 2 000 запитів на місяць, необмежені публічні промпти й учасники команди; Pro — $12 на місяць (10 000 запитів, приватні промпти, повний API); Team — $20 за користувача на місяць (50 000 запитів, оцінювання, конвеєри); при річній оплаті на 25% дешевше; Enterprise — за запитом, з SSO і SOC 2.', 'PromptHub helps you store, test and improve prompts. Prompts have version history, can be run in batches across models with results compared, and you can set up evaluations and multi-step pipelines and call them via API. There is a community with public prompts. Plans: Free — 2,000 requests a month, unlimited public prompts and team members; Pro — $12 a month (10,000 requests, private prompts, full API); Team — $20 per user a month (50,000 requests, evaluations, pipelines); 25% cheaper billed yearly; Enterprise on request, with SSO and SOC 2.', 'Версії промптів
Пакетне тестування на різних моделях
Оцінювання й конвеєри
API та спільнота', 'Prompt versioning
Batch testing across models
Evaluations and pipelines
API and community', 'Команди, які працюють з промптами в продуктах або щоденній роботі з AI.', 'Teams that work with prompts in products or in daily AI work.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
